const FIRST_SURFACE = "clinician-workspace";

/**
 * The manifest role the identity's roles name (by id or label, case-insensitive). FAILS CLOSED, like
 * the route guard's `canAccess`: with gating on, an identity that names none of the manifest's roles
 * (anonymous, or a role the prototype never declared) has NO role — never the default one's menu.
 */
function roleOf(raw: readonly string[]): string | null {
  if (!GATING) return null;
  const wanted = new Set(raw.map((r) => r.toLowerCase()));
  const hit = ROLES.find(
    (r) => wanted.has(r.id.toLowerCase()) || wanted.has(r.label.toLowerCase()),
  );
  return hit?.id ?? null;
}

/**
 * Every manifest role the identity names (by id or label, case-insensitive), in the manifest's order — the roles the
 * viewer HOLDS. The backend authorizes by their union; the active one only decides what the menu shows.
 */
function heldRolesOf(raw: readonly string[]): ShellViewModel['roles'] {
  if (!GATING) return [];
  const wanted = new Set(raw.map((r) => r.toLowerCase()));
  return ROLES.filter(
    (r) => wanted.has(r.id.toLowerCase()) || wanted.has(r.label.toLowerCase()),
  );
}

/** Up to two upper-case initials: first letters of the first and last word of the name. */
function initialsOf(name: string): string {
  const words = name.split(' ').filter((w) => w !== '');
  const first = words[0];
  if (first === undefined) return '';
  const last = words.length > 1 ? words[words.length - 1] : undefined;
  return (first.charAt(0) + (last === undefined ? '' : last.charAt(0))).toUpperCase();
}

/** The identity menu's data: the profile name (the e-mail when there is none) and the resolved role's label. */
function identityOf(
  who: ReturnType<typeof useIdentity>['identity'],
  roleLabel: string,
): ShellViewModel['identity'] {
  if (who === null || who === undefined) return null;
  const name = ((who.firstName ?? '') + ' ' + (who.lastName ?? '')).trim() || who.email;
  return {
    name,
    ...(who.email === '' ? {} : { email: who.email }),
    roleLabel,
    initials: initialsOf(name),
  };
}

let warnedUnmatched = false;

/**
 * The route the pathname belongs to. The table holds the BARE path of each page; the app registers
 * it with optional trailing params (`/phone/tasks/:id?`), so a detail URL must still resolve to its
 * own surface: exact match first, then the path as a prefix (`<path>/*`). The longest pattern wins
 * (`/phone/tasks/7` is the phone surface's, not whatever shorter route happens to prefix it).
 */
function routeOf(pathname: string): (typeof ROUTES)[number] | undefined {
  let best: (typeof ROUTES)[number] | undefined;
  for (const r of ROUTES) {
    if (best !== undefined && r.path.length <= best.path.length) continue;
    const exact = matchPath({ path: r.path, end: true }, pathname) !== null;
    const nested =
      r.path !== '/' &&
      matchPath({ path: r.path + '/*', end: true }, pathname) !== null;
    if (exact || nested) best = r;
  }
  return best;
}

export function PatientPathwayShellContainer({ children }: { readonly children: ReactNode }) {
  const { pathname } = useLocation();
  const { identity } = useIdentity();
  const navigate = useNavigate();
  const storedRole = useStoredActiveRole();
  const hit = routeOf(pathname);
  const surfaceId = hit?.surface ?? FIRST_SURFACE;
  const surface = SURFACES[surfaceId];
  if (surface === undefined) throw new Error('shell-container-unknown-surface: ' + surfaceId);
  const held = heldRolesOf(identity?.roles ?? []);
  // The active role: the remembered one while the viewer still holds it, else the first held (what the app did before).
  const role = pickActiveRole(held.map((r) => r.id), storedRole);
  // Gating on and no matching role: an EMPTY menu and a named notice (once), never another role's.
  const unmatched = GATING && role === null;
  if (unmatched && !warnedUnmatched) {
    warnedUnmatched = true;
    console.warn('shell-container-role-unmatched: the identity names none of the prototype roles; the nav is empty (' + (identity?.roles ?? []).join(',') + ')');
  }
  const key = role ?? NO_GATING_KEY;
  const vm: ShellViewModel = {
    surface: { id: surfaceId, kind: surface.kind, title: surface.title, canvas: surface.canvas },
    current: hit?.slug ?? '',
    nav: unmatched ? [] : (surface.nav[key] ?? []),
    actions: unmatched ? [] : (surface.actions[key] ?? []),
    // The prototype's action bag (search/palette, create, bell, profile, sign out): an unmatched role gets an EMPTY one, like the nav.
    shellActions: unmatched ? {} : surface.shellActions?.[key],
    brand: BRAND,
    role,
    identity: identityOf(identity, ROLES.find((r) => r.id === role)?.label ?? ''),
    roles: (held.length > 1 ? held : []),
    // Only with 2+ held roles (a single-role viewer gets no switcher). The new role's landing is what `/` resolves to.
    ...(held.length > 1
      ? {
          onSwitchRole: (id: string) => {
            if (!held.some((r) => r.id === id)) return;
            setActiveRole(id);
            navigate('/');
          },
        }
      : {}),
  };
  return <PatientPathwayShell vm={vm}>{children}</PatientPathwayShell>;
}
